export type ModernClassDecorator = <T extends abstract new (...args: any[]) => any>(value: T, context: ClassDecoratorContext<T>) => T | void;
export type ModernFieldDecorator = <This, Value>(value: undefined, context: ClassFieldDecoratorContext<This, Value>) => ((this: This, initialValue: Value) => Value) | void;
export type ModernMethodDecorator = <This, Value extends (this: This, ...args: any[]) => any>(value: Value, context: ClassMethodDecoratorContext<This, Value>) => Value | void;
export type ModernGetterDecorator = <This, Value>(value: (this: This) => Value, context: ClassGetterDecoratorContext<This, Value>) => ((this: This) => Value) | void;
export type ModernSetterDecorator = <This, Value>(value: (this: This, value: Value) => void, context: ClassSetterDecoratorContext<This, Value>) => ((this: This, value: Value) => void) | void;
export type ModernAccessorDecorator = <This, Value>(value: {
    get: (this: This) => Value;
    set: (this: This, value: Value) => void;
}, context: ClassAccessorDecoratorContext<This, Value>) => {
    get?: (this: This) => Value;
    set?: (this: This, value: Value) => void;
    init?: (this: This, initialValue: Value) => Value;
} | void;
export type ModernDecorators = ModernClassDecorator & ModernFieldDecorator & ModernMethodDecorator & ModernGetterDecorator & ModernSetterDecorator & ModernAccessorDecorator;
